CREATE TEMP TABLE rebka_image_path_map (old_url text PRIMARY KEY, new_url text NOT NULL) ON COMMIT DROP;
UPDATE public.categories t SET image_url = m.new_url FROM rebka_image_path_map m WHERE t.image_url = m.old_url;
UPDATE public.brands t SET logo_url = m.new_url FROM rebka_image_path_map m WHERE t.logo_url = m.old_url;
UPDATE public.products t SET image_url = m.new_url FROM rebka_image_path_map m WHERE t.image_url = m.old_url;
UPDATE public.banners t SET image_url = m.new_url FROM rebka_image_path_map m WHERE t.image_url = m.old_url;
UPDATE public.banners t SET mobile_image_url = m.new_url FROM rebka_image_path_map m WHERE t.mobile_image_url = m.old_url;
UPDATE public.testimonials t SET avatar_url = m.new_url FROM rebka_image_path_map m WHERE t.avatar_url = m.old_url;
UPDATE public.posts t SET image_url = m.new_url FROM rebka_image_path_map m WHERE t.image_url = m.old_url;